List<String> separateParenGroups(String parenString) {
  List<String> groups = [];
  List<String> current = [];
  int balance = 0;

  for (int i = 0; i < parenString.length; i++) {
    String char = parenString[i];
    if (char == '(') {
      balance++;
      current.add(char);
    } else if (char == ')') {
      balance--;
      current.add(char);
      if (balance == 0) {
        groups.add(current.join(''));
        current.clear();
      }
    }
  }
  return groups;
}
