List<double> findClosestElements(List<double> numbers) {
  if (numbers.isEmpty) return [];

  List<double> result = [];
  double closestDiff = double.infinity;

  for (int i = 0; i < numbers.length; i++) {
    double current = numbers[i];
    for (int j = 0; j < numbers.length; j++) {
      if (i == j) continue;
      double other = numbers[j];
      double diff = (current - other).abs();
      if (diff < closestDiff) {
        closestDiff = diff;
        result = [current, other];
      } else if (diff == closestDiff && result.isNotEmpty) {
        result.add(current);
        result.add(other);
      }
    }
  }

  result.sort();
  return result;
}
