List<double> rescaleToUnit(List<double> numbers) {
  if (numbers.isEmpty) return numbers;
  double minVal = numbers.reduce((a, b) => a < b ? a : b);
  double maxVal = numbers.reduce((a, b) => a > b ? a : b);
  double range = maxVal - minVal;
  if (range == 0) return List<double>.filled(numbers.length, 0.0);
  return numbers.map((n) => (n - minVal) / range).toList();
}
