int primeFib(int n) {
  if (n <= 0) return 0;

  List<int> fibs = [0, 2];

  while (n > 0) {
    int nextFib = fibs[fibs.length - 1] + fibs[fibs.length - 2];
    fibs.add(nextFib);

    int candidate = fibs.last;
    n--;

    if (candidate < 2) {
      continue;
    }

    bool isPrime = true;
    int limit = (candidate.toDouble().sqrt()).toInt();
    if (limit > candidate - 1) {
      limit = candidate - 1;
    }

    for (int i = 2; i <= limit; i++) {
      if (candidate % i == 0) {
        isPrime = false;
        break;
      }
    }

    if (!isPrime) {
      n++;
    }
  }

  return fibs.last;
}
