int search(List<int> lst) {
  final n = lst.length;
  final counts = List<int>.filled(n + 1, 0);
  final iterator = lst.iterator;
  while (iterator.moveNext()) {
    final value = iterator.current;
    counts[value] = counts[value] + 1;
  }
  for (int i = 1; i < counts.length; i++) {
    if (counts[i] >= i) {
      return i;
    }
  }
  return -1;
}
