bool isNested(String string) {
  List<int> open = [];
  List<int> close = [];

  for (int i = 0; i < string.length; i++) {
    if (string[i] == '(') {
      open.add(i);
    } else if (string[i] == ')') {
      close.add(i);
    }
  }

  List<int> reversedClose = close.reversed.toList();
  int count = 0;
  int j = 0;

  for (int i = 0; i < open.length; i++) {
    if (j >= reversedClose.length) break;
    if (open[i] < reversedClose[j]) {
      count++;
      j++;
    }
  }

  return count >= 2;
}
