String fixSpaces(String text) {
  String result = '';
  int lastSpace = 0; // index after the last space processed
  int current = 0;   // current position in original string (non-space count)

  for (int i = 0; i < text.length; i++) {
    if (text[i] == ' ') {
      int wordLength = current - lastSpace;
      if (wordLength > 2) {
        // Word longer than 2: replace with a single hyphen
        result = text[i] + '-' + result;
      } else if (wordLength > 0) {
        // Word length 1 or 2: replace with hyphens of the same length
        result = text[i] + ('-' * wordLength) + result;
      } else {
        // Consecutive spaces: just keep the space
        result = text[i] + result;
      }
      lastSpace = i + 1;
      current = i + 1;
    } else {
      current++;
    }
  }

  // Process the final word if any
  int wordLength = current - lastSpace;
  if (wordLength > 2) {
    result = '-' + result;
  } else if (wordLength > 0) {
    result = ('-' * wordLength) + result;
  }

  return result;
}
