String fixSpaces(String text) {
  StringBuffer buffer = StringBuffer();
  int spaceCount = 0;
  int index = 0;
  int length = text.length;

  while (index < length) {
    String char = text[index];
    if (char == ' ') {
      spaceCount++;
    } else {
      if (spaceCount > 2) {
        buffer.write('   ');
      } else if (spaceCount > 0) {
        buffer.write(' ' * spaceCount);
      }
      buffer.write(char);
      spaceCount = 0;
    }
    index++;
  }

  if (spaceCount > 2) {
    buffer.write('   ');
  } else if (spaceCount > 0) {
    buffer.write(' ' * spaceCount);
  }

  return buffer.toString();
}
