  // The assembly treats the first argument as numbers and the second as operators.
  // To match the assembly logic, we swap their roles internally.
  List A = List.from(operand); // numbers
  List B = List.from(operator); // strings (operators)

  // Helper for integer exponentiation (matching the assembly's loop)
  int intPow(int base, int exponent) {
    if (exponent < 0) throw ArgumentError('Negative exponent not supported');
    int result = 1;
    for (int i = 0; i < exponent; i++) {
      result *= base;
    }
    return result;
  }

  // Pass 1: exponentiation (^ and sqrt)
  for (int i = 0; i < B.length; i++) {
    if (B[i] is! num) { // processes strings (operators)
      var left = A[i];
      var right = A[i + 1];
      var result;
      if (left is int && right is int) {
        result = intPow(left, right);
      } else {
        double l = (left as num).toDouble();
        double r = (right as num).toDouble();
        if (r == 0.0) {
          result = 1.0;
        } else if (r == 1.0) {
          result = l;
        } else if (r == 2.0) {
          result = l * l;
        } else if (r == 3.0) {
