      A.removeAt(i + 1);
      B.removeAt(i + 1);
    }
  }

  // Pass 2: multiplication (*)
  for (int i = 0; i < B.length; i++) {
    if (B[i] is! num) {
      var left = A[i] as num;
      var right = A[i + 1] as num;
      A[i] = left * right;
      A.removeAt(i + 1);
      B.removeAt(i + 1);
    }
  }

