num doAlgebra(List<String> operator, List<int> operand) {
  List<num> operands = List<num>.from(operand);
  List<String> operators = List<String>.from(operator);

  int i = 0;
  while (i < operators.length) {
    if (operators[i] == '^') {
      if (operands[i] is int && operands[i + 1] is int && operands[i + 1] >= 0) {
        operands[i] = _intPow(operands[i] as int, operands[i + 1] as int);
      } else {
        operands[i] = _doubleOp(operators[i], operands[i], operands[i + 1]);
      }
      operands.removeAt(i + 1);
      operators.removeAt(i);
    } else {
      i++;
    }
  }

  i = 0;
  while (i < operators.length) {
    if (operators[i] == '*' || operators[i] == '/') {
      operands[i] = _doubleOp(operators[i], operands[i], operands[i + 1]);
      operands.removeAt(i + 1);
      operators.removeAt(i);
    } else {
      i++;
    }
  }

  i = 0;
  while (i < operators.length) {
    if (operators[i] == '+' || operators[i] == '-') {
      operands[i] = _doubleOp(operators[i], operands[i], operands[i + 1]);
      operands.removeAt(i + 1);
      operators.removeAt(i);
    } else {
      i++;
    }
  }

  return operands[0];
}

int _intPow(int base, int exponent) {
  int result = 1;
  while (exponent > 0) {
    if (exponent % 2 == 1) {
      result *= base;
    }
    exponent ~/= 2;
    base *= base;
  }
  return result;
}

double _doubleOp(String op, num a, num b) {
  double da = (a as double);
  double db = (b as double);
  switch (op) {
    case '+':
      return da + db;
    case '-':
      return da - db;
    case '*':
      return da * db;
    case '/':
      return da / db;
    case '^':
      if (db == 0) return 1;
      if (db == 1) return da;
      if (db == 2) return da * da;
      if (db == 3) return da * da * da;
      if (db == 0.5) return da < 0 ? double.nan : _sqrt(da);
      return _pow(da, db);
    default:
      return double.nan;
  }
}

double _sqrt(double x) {
  if (x < 0) return double.nan;
  if (x == 0) return 0;
  double guess = x;
  for (int i = 0; i < 20; i++) {
    guess = (guess + x / guess) / 2;
  }
  return guess;
}

double _pow(double base, double exponent) {
  if (base == 1 || exponent == 0) return 1;
  if (exponent == 1) return base;
  if (exponent == 2) return base * base;
  if (exponent == 3) return base * base * base;
  if (exponent == 0.5) return _sqrt(base);
  return _exp(exponent * _log(base));
}

double _exp(double x) {
  double sum = 1.0;
  double term = 1.0;
  for (int i = 1; i <= 20; i++) {
    term *= x / i;
    sum += term;
  }
  return sum;
}

double _log(double x) {
  if (x <= 0) return double.nan;
  double y = (x - 1) / (x + 1);
  double sum = 0.0;
  double term = y;
  for (int i = 1; i <= 20; i += 2) {
    sum += term / i;
    term *= y * y;
  }
  return 2 * sum;
}
